using ull = unsigned long long;

ull count_down(ull u, int d, ull N) {
    if (u == 0) return 0;
    if (d >= 63) return 0;
    __int128 L = (__int128)u << d;
    if (L > N) return 0;
    __int128 R = L + ((__int128)1 << d) - 1;
    if (R > N) R = N;
    return (ull)(R - L + 1);
}

