    while (T--) {
        ull N, X, K; cin >> N >> X >> K;
        if (K == 0) { cout << 1 << '\n'; continue; }
        ull ans = 0;
        ans += count_down(X, K, N);
        for (ull a = 1; a <= K; ++a) {
            if (((__int128)1 << a) > X) break;
            ull A = X >> a;
            ull b = K - a;
            if (b == 0) ans += 1;
            else {
                ull other = ((X >> (a-1)) & 1) ? (2*A) : (2*A + 1);
                ans += count_down(other, b-1, N);
            }
        }
